public class ReceiptStylerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            ReceiptStyler styler = new ReceiptStyler("fruit");

            String simple = styler.render(new String[] { "milk", "  eggs  " });
            check("two normal lines",
                    "== FRUIT ==\n* milk\n* eggs\n== END ==",
                    simple);

            String withBlanks = styler.render(new String[] { "", "   ", null });
            check("blank, spaces and null lines",
                    "== FRUIT ==\n* (blank)\n* (blank)\n* (blank)\n== END ==",
                    withBlanks);

            check("no body lines at all",
                    "== FRUIT ==\n== END ==",
                    styler.render(new String[0]));

            ReceiptStyler shouty = new ReceiptStyler("MiXeD Case");
            check("banner upper cases the title",
                    "== MIXED CASE ==\n* a\n== END ==",
                    shouty.render(new String[] { "a" }));

            check("getTitle is inherited unchanged", "fruit", styler.getTitle());

            ReceiptSection asBase = styler;
            check("hooks are used through the base type",
                    "== FRUIT ==\n* tea\n== END ==",
                    asBase.render(new String[] { " tea " }));

            java.lang.reflect.Method m = ReceiptStyler.class.getDeclaredMethod("decorate", String.class);
            boolean visible = java.lang.reflect.Modifier.isProtected(m.getModifiers())
                    || java.lang.reflect.Modifier.isPublic(m.getModifiers());
            check("decorate is declared protected (or public)", true, visible);
        } catch (NoSuchMethodException e) {
            System.out.println("FAIL  decorate(String) is declared in ReceiptStyler -- expected true but got false");
            failures++;
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- expected none but got " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

