/**
 * Provided -- do not edit.
 *
 * A receipt section. render(...) is public and final: callers always get the
 * same overall shape. Subclasses change only the two PROTECTED hook methods.
 */
abstract class ReceiptSection {

    private final String title;

    protected ReceiptSection(String title) {
        this.title = title;
    }

    public final String render(String[] lines) {
        StringBuilder sb = new StringBuilder();
        sb.append(banner(title)).append("\n");
        for (String line : lines) {
            sb.append(decorate(line)).append("\n");
        }
        sb.append(banner("end"));
        return sb.toString();
    }

    /** Hook: how one body line is shown. Default leaves it unchanged. */
    protected String decorate(String line) {
        return line;
    }

    /** Hook: how a banner line is shown. Default wraps it in square brackets. */
    protected String banner(String text) {
        return "[" + text + "]";
    }

    protected final String getTitle() {
        return title;
    }
}

public class ReceiptStyler extends ReceiptSection {

    public ReceiptStyler(String title) {
        super(title);
    }

    @Override
    protected String decorate(String line) {
        if (line == null) {
            return "* (blank)";
        }
        String trimmed = line.trim();
        if (trimmed.isEmpty()) {
            return "* (blank)";
        }
        return "* " + trimmed;
    }

    @Override
    protected String banner(String text) {
        return "== " + text.toUpperCase() + " ==";
    }
}
